// Percent fields are bonuses above the baseline: 26% -> native multiplier 1.26.
function meleeRow(w){return ['H','L','F','2H'].includes(w.family)}
function weaponTargetsPanel(){const bonusActive=state.weapons.some(w=>w.enabled&&(w.meleeDefense>0||w.attackBonus>0)),legacy=state.importedRules.filter(e=>e.enabled&&e.group==='Weapons'),broad=state.weapons.filter(w=>w.enabled&&meleeRow(w)&&!(w.meleeDefense>0||w.attackBonus>0));return `<div class="card"><h3>Weapon targets</h3><p>Each row requires its damage minimum <strong>and</strong> every bonus entered in that row. Separate rows are alternatives. Enter 0 to ignore a bonus.</p><div class="row"><label>New / bulk defense minimum (%) <input aria-label="Defense target default" type="number" min="0" max="1000" step="any" value="${state.weaponBonusDefaults.meleeDefense}" onchange="bonusDefault('meleeDefense',this.value)"></label><label>New / bulk attack minimum (%) <input aria-label="Attack target default" type="number" min="0" max="1000" step="any" value="${state.weaponBonusDefaults.attackBonus}" onchange="bonusDefault('attackBonus',this.value)"></label><button onclick="applyBonusDefaults()">Apply minimums to existing bonus targets</button></div><div class="toolbar"><button onclick="makeBonusTargets()">Create defensive + accuracy targets</button><button onclick="moveWeaponRules()">Move supported imported weapons into controls</button></div><p class="muted">Create targets replaces enabled melee rows with two copies: defense ≥${state.weaponBonusDefaults.meleeDefense}% and attack ≥${state.weaponBonusDefaults.attackBonus}%. Both numbers and damage remain editable. Other weapon types stay as they are.</p>${bonusActive&&(legacy.length||broad.length)?`<div class="notice">${legacy.length} active imported weapon rule(s) and ${broad.length} active melee row(s) may still collect weapons without these bonuses. <button onclick="tab='Imported';render()">Review imported rules</button></div>`:''}${legacy.length?'<p>Imported weapon rules remain active until moved or disabled. Use the move button first to retain their actual damage values and conditions.</p>':''}</div>${state.weapons.some(w=>w.maximum!==''&&w.maximum!=null)?'<div class="notice">The original engine does not support upper damage caps. <button onclick="clearDamageCaps()">Remove old upper caps</button></div>':''}<div class="card"><div class="weaponhead"><label>Starting profile <select onchange="preset(this.value)">${Object.keys(DATA.profiles).map(p=>`<option ${state.weaponPreset===p?'selected':''}>${esc(p)}</option>`).join('')}</select></label><input aria-label="Search weapon types" placeholder="Search · sword, bow, war…" value="${esc(weaponQuery)}" oninput="filterWeapons(this.value)"><button onclick="resetWeapons()">Reset weapon targets to profile defaults</button></div><p>Damage starts with your DreamWeave profile’s effective damage values. Bonuses include innate values plus applicable cantrips: 19% innate + Legendary Defender 9% = 28%.</p><p class="muted">No character-cast Defender or Heart Seeker buff is assumed. Attack bonus improves accuracy; it is not hit chance. Wield tiers remain available. Wands use elemental multipliers for damage.</p><div class="tablewrap"><table><thead><tr><th>ENABLED</th><th>TARGET / TYPE</th><th>WIELD</th><th>DAMAGE MIN</th><th>BUFFED MELEE DEFENSE %</th><th>BUFFED ATTACK %</th><th></th></tr></thead><tbody>${state.weapons.map((w,i)=>`<tr data-weapon="${esc((w.family+' '+w.kind+' '+(w.targetName||'')).toLowerCase())}"><td><input aria-label="Enable weapon target ${i+1}" type="checkbox" ${w.enabled?'checked':''} onchange="weapon(${i},'enabled',this.checked);render()"></td><td><input aria-label="Weapon target ${i+1} name" value="${esc(w.targetName||w.kind)}" onchange="weapon(${i},'targetName',this.value)"><small>${esc(w.family+' · '+w.kind)} · default OD +${w.od}</small></td><td>${esc(w.wield)}</td><td><input aria-label="Weapon target ${i+1} minimum damage" type="number" min="0" step="any" value="${w.minimum}" onchange="weapon(${i},'minimum',this.value)"><small>${esc(w.unit)}</small></td><td><input aria-label="Weapon target ${i+1} minimum buffed melee defense" type="number" min="0" max="1000" step="any" value="${w.meleeDefense??0}" onchange="weapon(${i},'meleeDefense',this.value);render()"></td><td><input aria-label="Weapon target ${i+1} minimum buffed attack bonus" type="number" min="0" max="1000" step="any" value="${w.attackBonus??0}" onchange="weapon(${i},'attackBonus',this.value);render()"></td><td><button onclick="duplicateWeapon(${i})">Duplicate</button><button onclick="removeWeapon(${i})">Remove</button></td></tr>`).join('')}</tbody></table></div><p id="weaponEmpty" class="muted" hidden>No weapon types match.</p></div>`}
function duplicateWeapon(i){if(state.weapons.length>=2000){message('Too many targets','Remove an unused target first.');return}let w=structuredClone(state.weapons[i]);w.targetName=(w.targetName||w.kind)+' copy';state.weapons.splice(i+1,0,w);persist();render()}
function removeWeapon(i){state.weapons.splice(i,1);persist();render()}
function makeBonusTargets(){const md=state.weaponBonusDefaults.meleeDefense,attack=state.weaponBonusDefaults.attackBonus;if(md<=0||attack<=0){message('Choose positive bonus minimums','Use positive percentages to create defensive and accuracy targets.');return}let selected=state.weapons.filter(w=>w.enabled&&meleeRow(w)&&!(w.meleeDefense>0||w.attackBonus>0));if(!selected.length){message('Choose melee targets first','Enable the melee damage rows to replace. If your profile is imported, move its supported weapons into controls first.');return}if(state.weapons.length+selected.length>2000){message('Too many targets','Remove unused targets first.');return}if(!confirm('Replace '+selected.length+' enabled melee damage row(s) with separate defensive and accuracy targets? Each keeps its current damage minimum; defense starts at '+md+'%, attack at '+attack+'%. Imported rules and other weapon rows remain unchanged.'))return;const chosen=new Set(selected);state.weapons=state.weapons.flatMap(w=>chosen.has(w)?[{...structuredClone(w),targetName:'Defensive '+w.kind,meleeDefense:md,attackBonus:0},{...structuredClone(w),targetName:'Accurate '+w.kind,meleeDefense:0,attackBonus:attack}]:[w]);persist();render()}
function weaponDamageCondition(r){return r.requirements.find(q=>[2001,2003].includes(q.type)||q.type===2005&&UTL.parts(q)[1]==='152')}
function moveWeaponRules(){const templates=Object.entries(UTLDATA.weapons).flatMap(([preset,rules])=>rules.map(r=>({preset,r,w:DATA.profiles[preset].find(w=>w.source===r.name)}))),signature=r=>r.requirements.filter(q=>q.type!==9999&&q.type!==1001&&q!==weaponDamageCondition(r)).map(q=>q.type+':'+q.data).sort().join('|');let moved=0,rows=[];for(const e of state.importedRules){if(e.group!=='Weapons'||!e.enabled||e.rule.expression||e.rule.action!==1)continue;const damage=weaponDamageCondition(e.rule);if(!damage)continue;let match=templates.find(t=>signature(t.r)===signature(e.rule)&&weaponDamageCondition(t.r).type===damage.type);if(!match?.w)continue;rows.push({e,w:{...structuredClone(match.w),targetName:e.rule.name,minimum:+UTL.parts(damage)[0],template:UTL.clone(e.rule)}})}if(!rows.length){message('No supported weapon rules to move','Rules with extra conditions remain intact under All rules.');return}if(state.weapons.length+rows.length>2000){message('Too many targets','Remove unused targets first.');return}if(!confirm('Move '+rows.length+' original weapon rules into editable controls with their damage values, wield conditions, and pack-space requirements intact? Their imported entries will be disabled.'))return;for(const {e,w} of rows){if(typeof baseline==='function')baseline(e);state.weapons.push(w);e.enabled=false;moved++}persist();render()}

function bonusDefault(field,value){const n=Number(value);if(value===''||!Number.isFinite(n)||n<0||n>1000){message('Invalid percentage','Enter a percentage from 0 to 1000.');render();return}state.weaponBonusDefaults[field]=n;persist()}
function applyBonusDefaults(){if(!confirm('Apply these minimums to all weapon targets that already use the corresponding bonus? Unused bonus fields and damage values remain unchanged.'))return;for(const w of state.weapons){if(w.meleeDefense>0)w.meleeDefense=state.weaponBonusDefaults.meleeDefense;if(w.attackBonus>0)w.attackBonus=state.weaponBonusDefaults.attackBonus}persist();render()}
